package com.lexorion.payroll.tenant;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;import java.util.List;import org.springframework.http.HttpHeaders;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;@Component public class TrustedPayrollFilter extends OncePerRequestFilter{public static final String WORKSPACE_HEADER="X-Lexorion-Workspace";private final PayrollAuthorityClient authority;private final TrustedPayrollContextHolder contexts;private final AuthorityRequestContext requests;public TrustedPayrollFilter(PayrollAuthorityClient a,TrustedPayrollContextHolder c,AuthorityRequestContext r){authority=a;contexts=c;requests=r;}protected boolean shouldNotFilter(HttpServletRequest r){return !r.getRequestURI().startsWith("/api/payroll/");}protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain chain)throws ServletException,IOException{String token=r.getHeader(HttpHeaders.AUTHORIZATION),key=r.getHeader(WORKSPACE_HEADER);if(token==null||!token.startsWith("Bearer ")||key==null||!key.matches("^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$")){s.sendError(401,"Trusted Payroll context is required");return;}try{TrustedPayrollContext c=authority.validate(key,token,r.getHeader(HttpHeaders.HOST),r.getHeader("X-Lexorion-Organization"));if(c==null||!key.equals(c.workspaceKey())){s.sendError(403,"Payroll workspace access denied");return;}contexts.set(c);requests.set(new AuthorityRequestContext.Credentials(token,r.getHeader(HttpHeaders.HOST),c.organizationSlug()));SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(c.workspaceKey(),null,List.of(new SimpleGrantedAuthority("ROLE_"+c.role()))));chain.doFilter(r,s);}catch(RuntimeException ex){s.sendError(403,"Payroll workspace access denied");}finally{contexts.clear();requests.clear();SecurityContextHolder.clearContext();}}}
